async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  const decoder = new TextDecoder();

  let accepted = 0;
  let rejected = 0;
  let lineNumber = 1;
  let stopped = false;
  let reachedEOF = false;
  let cancelled = false;
  let lineParts = [];

  const cancelOnce = async () => {
    if (!cancelled) {
      cancelled = true;
      await reader.cancel();
    }
  };

  const consumeLine = async (line) => {
    const lineNumberForVisitor = lineNumber++;

    if (/^[\u0009\u0020]*$/.test(line)) {
      return false;
    }

    let value;
    try {
      value = JSON.parse(line);
    } catch {
      rejected++;
      return false;
    }

    accepted++;
    const result = await visitor({
      line: lineNumberForVisitor,
      value
    });

    return result === false;
  };

  const consumeText = async (text) => {
    let start = 0;

    while (true) {
      const newline = text.indexOf("\n", start);
      if (newline === -1) {
        if (start < text.length) {
          lineParts.push(text.slice(start));
        }
        return false;
      }

      lineParts.push(text.slice(start, newline));

      let line = lineParts.join("");
      lineParts = [];

      if (line.endsWith("\r")) {
        line = line.slice(0, -1);
      }

      if (await consumeLine(line)) {
        return true;
      }

      start = newline + 1;
    }
  };

  try {
    while (true) {
      const record = await reader.read();

      if (record.done) {
        if (await consumeText(decoder.decode())) {
          stopped = true;
          await cancelOnce();
          return { accepted, rejected, stopped };
        }

        if (lineParts.length > 0) {
          const line = lineParts.join("");
          lineParts = [];

          if (await consumeLine(line)) {
            stopped = true;
            await cancelOnce();
            return { accepted, rejected, stopped };
          }
        }

        reachedEOF = true;
        return { accepted, rejected, stopped };
      }

      if (await consumeText(decoder.decode(record.value, { stream: true }))) {
        stopped = true;
        await cancelOnce();
        return { accepted, rejected, stopped };
      }
    }
  } catch (error) {
    await cancelOnce();
    throw error;
  } finally {
    if (!reachedEOF && !cancelled) {
      await cancelOnce();
    }
    reader.releaseLock();
  }
}
